/**
 * Parameters for the POI categories service.
 *
 * Results are cached in memory per language. The first call for a language fetches
 * from the API, and the cache serves later calls.
 *
 * @group POI Categories
 */
type POICategoriesParams = CommonServiceParams<GetObject, POICategoriesResponseAPI> & {
  /**
   * Keywords matched client-side against every category's name and synonyms, strongest match first.
   *
   * - A category code (`'CAFE'`) matches that category only. Any other filter ranks an exact name or
   *   synonym first, then a name or synonym the filter starts, one holding it as a later word, and
   *   last one holding it as a substring. Each filter keeps only the matches ranking close to its best.
   * - Matching ignores case, accents and punctuation, and spaces too in the substring tiers. `'bar'`
   *   finds Bar but not Nail Salon ("Nail Bar"), and `'bookstore'` finds Book Shop ("Book Store").
   * - Several filters merge round-robin, so each filter's best match comes first, one entry per `code`.
   *   A category ranking below its matched parent is left out, because the parent already covers it.
   *
   * A blank filter matches nothing. Omit `filters` to return all categories.
   *
   * @example
   * ```ts
   * // All categories (no filters)
   * {}
   *
   * // Categories matching "gym"
   * { filters: ['gym'] }
   *
   * // Categories matching either "gym" or "italian restaurant"
   * { filters: ['gym', 'italian restaurant'] }
   * ```
   */
  filters?: string[];
};
/**
 * The {@link POICategoriesParams} for `resolvePOICategories`, with the words to resolve required
 * in `filters`.
 *
 * @group POI Categories
 */
type ResolvePOICategoriesParams = POICategoriesParams & Required<Pick<POICategoriesParams, 'filters'>>;
