/**
 * Retrieves the list of POI category types supported by the TomTom Search API.
 *
 * The returned `code` values (`POICategory`) serve two purposes:
 * - Pass to `discoverPlaces({ filters: { poiCategories } })` to filter search results by category.
 * - Pass as `POIsModule` `filters.categories` to filter the map's built-in POI icons.
 *   Generic parent codes (e.g. `'RESTAURANT'`) work there, but overly specific child codes
 *   (e.g. `'ITALIAN_RESTAURANT'`) don't, so use a parent or a `POICategoryGroup` instead.
 *
 * The list is cached per language, as {@link POICategoriesParams} describes, and filtered calls read it too.
 *
 * @param params - Optional parameters. Uses global `TomTomConfig` by default.
 *
 * @example
 * ```typescript
 * // All categories
 * const { poiCategories: all } = await getPOICategories();
 *
 * // Filtered by keyword, best match first
 * const { poiCategories: gyms } = await getPOICategories({ filters: ['gym'] });
 * gyms.forEach(category => console.log(category.code, category.name, category.childCategoryCodes));
 * ```
 *
 * @group POI Categories
 */
export declare const getPOICategories: (params?: POICategoriesParams) => Promise<POICategoriesResponse>;
/**
 * Wraps {@link getPOICategories} to return a flat array of `POICategory` codes, for the uses it lists.
 *
 * It accepts the same parameters as {@link getPOICategories}. Use `filters` to narrow by keyword.
 *
 * @param params - Optional parameters. Uses global `TomTomConfig` by default.
 *
 * @example
 * ```typescript
 * // All category codes
 * const codes = await getPOICategoryCodes();
 *
 * // Codes matching 'restaurant' — for search or generic map POI filtering
 * const restaurantCodes = await getPOICategoryCodes({ filters: ['restaurant'] });
 * ```
 *
 * @group POI Categories
 */
export declare const getPOICategoryCodes: (params?: POICategoriesParams) => Promise<POICategory[]>;
/**
 * Resolves category words, or codes, to the POI categories of one search, and reports the words that
 * match none.
 *
 * @remarks
 * Each filter matches as on {@link getPOICategories}, so a code stays itself. Each keeps its best three
 * codes, merged round-robin and capped at the 10 a search accepts. Codes alone skip the catalog request
 * and come back as given, deduplicated, so a sub-category stays beside its parent.
 * `discoverPlaces` runs the same lookup for `filters.poiCategoryQuery`, so call this first to decide what
 * to do about the words that match nothing. To browse every close match, use {@link getPOICategories}.
 *
 * @example
 * ```typescript
 * const { poiCategories, unmatched } = await resolvePOICategories({ filters: ['café', 'PHARMACY', 'xyzzy'] });
 * // unmatched: ['xyzzy']
 * const places = await discoverPlaces({ filters: { poiCategories }, geoBias: { position: [4.9041, 52.3676] } });
 * ```
 *
 * @group POI Categories
 */
export declare const resolvePOICategories: (parameters: ResolvePOICategoriesParams) => Promise<ResolvedPOICategories>;
