//#region src/revgeo/reverseGeocoding.d.ts
/**
 * Converts geographic coordinates into human-readable addresses (reverse geocoding).
 *
 * Reverse geocoding translates latitude/longitude coordinates into street addresses. This is
 * essential for location-based applications that display addresses from GPS coordinates or map
 * clicks.
 *
 * @remarks
 * Use it to convert GPS coordinates from tracked devices into addresses, display the address
 * when the user clicks on the map, show a readable location instead of coordinates, confirm
 * pickup/dropoff addresses from the driver's location, or display the current location of
 * vehicles or equipment.
 *
 * It returns the complete address hierarchy (street, city, state, country) and the result type
 * (address, street, or geography). You can narrow results to administrative areas with
 * `geographyTypes`, and match streets by direction with `heading`.
 *
 * @param params - The reverse geocoding parameters, including the coordinates.
 *
 * @returns The address for the given coordinates, or the queried point without `properties` where nothing matches.
 *
 * @example
 * ```typescript
 * // Get address for coordinates
 * const address = await reverseGeocode({
 *   position: [4.9041, 52.3676]  // Amsterdam coordinates
 * });
 * // Returns: Dam, 1012 Amsterdam, Netherlands
 *
 * // Get the address matched along a given travel direction
 * const specificAddress = await reverseGeocode({
 *   position: [-77.0369, 38.8977],  // Washington DC
 *   heading: 90                     // Traveling east
 * });
 *
 * // Get the containing municipality instead of the street
 * const municipality = await reverseGeocode({
 *   position: [-74.0060, 40.7128],  // New York
 *   geographyTypes: ['Municipality']
 * });
 * ```
 *
 * @see [Reverse Geocode API Documentation](https://docs.tomtom.com/search-api/documentation/reverse-geocoding-service/reverse-geocode)
 * @see [Places Quickstart Guide](https://docs.tomtom.com/maps-sdk-js/guides/services/places/quickstart)
 * @see [Reverse Geocoding Guide](https://docs.tomtom.com/maps-sdk-js/guides/services/places/reverse-geocoding)
 *
 * @group Reverse Geocoding
 */
export declare const reverseGeocode: (params: ReverseGeocodingParams) => Promise<ReverseGeocodingResponse>;
