//#region src/traffic-incident-details/trafficIncidentDetails.d.ts
/**
 * Fetches detailed information about traffic incidents.
 *
 * It queries incidents by a geographic bounding box, by a polygon, or by a list of incident IDs.
 * Results are GeoJSON Features whose geometry is a `Point` (localised incidents) or
 * a `LineString` (incidents spanning a stretch of road).
 *
 * @remarks
 * The query modes are:
 *
 * - Bounding box (`bbox`) returns all incidents within the given area.
 * - Polygon (`polygon`) returns the incidents that intersect a polygon, such as a city boundary.
 * - By IDs (`ids`) returns the specified incidents directly.
 *
 * The limits of each mode are on {@link TrafficIncidentDetailsByBBoxParams.bbox},
 * {@link TrafficIncidentDetailsByPolygonParams} and {@link TrafficIncidentDetailsByIdsParams.ids}.
 *
 * Each incident provides:
 * - Category (`category`): type of incident (accident, roadworks, jam, etc.)
 * - Delay magnitude: severity of the delay (`minor`, `moderate`, `major`, …)
 * - Geometry: exact location or extent of the incident on the road network
 * - Time information: start/end times and whether the incident is `present` or `future`
 * - Events: one or more detailed event descriptions
 *
 * @param params - Traffic Incident Details parameters (bbox, polygon or ids)
 *
 * @returns Promise resolving to a {@link TrafficIncidentDetails} object containing the matching incidents
 *
 * @example
 * ```typescript
 * // Query by bounding box (Amsterdam area)
 * const result = await trafficIncidentDetails({
 *   bbox: [4.728, 52.278, 5.080, 52.479]
 * });
 *
 * result.features.forEach(incident => {
 *   console.log(incident.properties.category);         // 'accident' | 'jam' | …
 *   console.log(incident.properties.magnitudeOfDelay); // 'minor' | 'major' | …
 *   console.log(incident.geometry);                    // Point or LineString
 * });
 * ```
 *
 * @example
 * ```typescript
 * // Query within a city boundary rather than its bounding box
 * const place = await geocodeOne('Amsterdam');
 * const result = await trafficIncidentDetails({
 *   polygon: await geometryData({ geometries: [place] })
 * });
 * ```
 *
 * @example
 * ```typescript
 * // Query specific incidents by ID
 * const result = await trafficIncidentDetails({
 *   ids: ['incident-id-1', 'incident-id-2']
 * });
 * ```
 *
 * @example
 * ```typescript
 * // Filter by category and include future incidents
 * const result = await trafficIncidentDetails({
 *   bbox: [4.728, 52.278, 5.080, 52.479],
 *   categoryFilter: ['accident', 'road-closed'],
 *   timeValidityFilter: ['present', 'future']
 * });
 * ```
 *
 * @see [Incident Details API Documentation](https://docs.tomtom.com/traffic-api/documentation/tomtom-orbis-maps/v2/traffic-incidents/incident-details)
 * @see [Incident Details Guide](https://docs.tomtom.com/maps-sdk-js/guides/services/traffic/traffic-incident-details)
 *
 * @group Traffic
 */
export declare const trafficIncidentDetails: (params: TrafficIncidentDetailsParams) => Promise<TrafficIncidentDetails>;
